+// Till sales: each dish sold consumes one recipe portion per qty, once per ticket.
+import { AppError } from "../errors.js";
+import { isInstant } from "../dates.js";
+import { consume } from "./batches.js";
+import { scaled } from "./recipes.js";
+
+/** Records validated sale lines atomically; skips tickets already imported and returns { tickets, dishes }. */
+export function recordSales(store, lines) {
+  const clean = lines.map((l) => {
+    const where = l.where ?? "sale";
+    if (typeof l.ticket !== "string" || !l.ticket.trim())
+      throw new AppError("bad_request", { reason: `${where}: ticket is required` });
+    if (!isInstant(l.soldAt))
+      throw new AppError("bad_request", { reason: `${where}: bad soldAt` });
+    if (!Number.isInteger(l.dishId) || l.dishId < 1)
+      throw new AppError("bad_request", { reason: `${where}: bad dishId` });
+    const dish = (store.data.dishes ?? []).find((d) => d.id === l.dishId);
+    if (!dish)
+      throw new AppError("bad_request", { reason: `${where}: unknown dish` });
+    const recipe = store.data.recipes.find((r) => r.id === dish.recipeId);
+    if (!recipe)
+      throw new AppError("bad_request", { reason: `${where}: unknown recipe` });
+    if (!Number.isInteger(l.qty) || l.qty < 1)
+      throw new AppError("bad_request", { reason: `${where}: bad qty` });
+    const soldAt = l.soldAt.endsWith("Z") ? l.soldAt : new Date(l.soldAt).toISOString();
+    return { where, ticket: l.ticket.trim(), soldAt, dishId: dish.id, recipe, qty: l.qty };
+  });
+
+  const snapshot = structuredClone(store.data);
+  try {
+    store.data.sales ??= [];
+    const imported = new Set(store.data.sales.map((s) => s.ticket));
+    const tickets = new Set();
+    let dishes = 0;
+    for (const row of clean) {
+      if (imported.has(row.ticket)) continue;
+      for (const need of scaled(row.recipe, row.qty)) {
+        if (need.qty <= 0) continue;
+        try {
+          consume(store, need.itemId, need.qty, { at: row.soldAt, ref: `sale:${row.ticket}` });
+        } catch (e) {
+          if (e instanceof AppError) throw new AppError(e.code, { ...e.params, where: row.where });
+          throw e;
+        }
+      }
+      store.data.sales.push({ ticket: row.ticket, soldAt: row.soldAt, dishId: row.dishId, qty: row.qty });
+      tickets.add(row.ticket);
+      dishes += row.qty;
+    }
+    return { tickets: tickets.size, dishes };
+  } catch (e) {
+    store.data = snapshot;
+    throw e;
+  }
+}
