+++ b/src/io/sales-import.js
@@ -0,0 +1,27 @@
+// Importing till sales from CSV (ticket,soldAt,dishId,qty). Every row is
+// validated first; one bad row or stock shortage leaves the store unchanged.
+import { AppError } from "../errors.js";
+import { recordSales } from "../domain/sales.js";
+import { parseCsv } from "./csv.js";
+
+const HEADER = ["ticket", "soldAt", "dishId", "qty"];
+
+/** Imports till sales from CSV text; returns { tickets, dishes } or throws naming the row. */
+export function importSales(store, text) {
+  const raw = parseCsv(text);
+  if (raw.length === 0) return { tickets: 0, dishes: 0 };
+  const [head, ...dataRows] = raw;
+  const keys = head.map((h) => h.trim());
+  for (const k of HEADER) {
+    if (!keys.includes(k)) throw new AppError("bad_request", { reason: `missing column ${k}` });
+  }
+  const lines = dataRows.map((cells, i) => {
+    const where = `row ${i + 2}`;
+    if (cells.length > keys.length) throw new AppError("bad_request", { reason: `${where}: too many columns` });
+    const r = Object.fromEntries(keys.map((k, idx) => [k, (cells[idx] ?? "").trim()]));
+    const dishId = /^\d+$/.test(r.dishId) ? Number(r.dishId) : NaN;
+    const qty = /^\d+$/.test(r.qty) ? Number(r.qty) : NaN;
+    return { where, ticket: r.ticket, soldAt: r.soldAt, dishId, qty };
+  });
+  return recordSales(store, lines);
+}
